	Q := mat.NewDense(n, n, []float64{4158016974890.2085, -345130904055.58923, -952663265929.7449, 363956709709.7752, 2152746117005.2986, -345130904055.58923, 4358258964261.007, -162257205383.95438, -1271912803015.4048, 569399655279.7114, -952663265929.7449, -162257205383.95438, 6299424961076.2, -1591000390187.9624, -2716754159313.2197, 363956709709.7752, -1271912803015.4048, -1591000390187.9624, 3910587717836.3745, 154331398854.73608, 2152746117005.2986, 569399655279.7114, -2716754159313.2197, 154331398854.73608, 2107169533824.2126})
